            Node("decl-1", "frame_mem", "frame_mem", "Replay an arbitrary native sequence by deleting its actual pair prefix.", "Source variable context (not a compiled telescope):\nvariable {V : Type*} [Fintype V] [DecidableEq V]\n\ntheorem frame_mem {K L : PreAbstractSimplicialComplex V} (S : Sequence K L)\n    (i : Nat) (hi : i ≤ S.pairs.length) (s : Finset V) :\n    s ∈ S.frames.getD i L ↔ s ∈ K ∧\n      ∀ P ∈ S.pairs.take i, s ≠ P.lower ∧ s ≠ P.upper", DescribeRole.Theorem),
            Node("decl-2", "frames_terminal", "frames_terminal", "The exact source contract below specifies D5.S3.Geometry.FiniteMatchingCollapse.frames_terminal.", "Source variable context (not a compiled telescope):\nvariable {V : Type*} [Fintype V] [DecidableEq V]\n\ntheorem frames_terminal {K L : PreAbstractSimplicialComplex V}\n    (S : Sequence K L) : S.frames.getD S.pairs.length L = L", DescribeRole.Theorem),
            Node("decl-3", "elementary_face_count", "elementary_face_count", "The exact source contract below specifies D5.S3.Geometry.FiniteMatchingCollapse.elementary_face_count.", "Source variable context (not a compiled telescope):\nvariable {V : Type*} [Fintype V] [DecidableEq V]\n\ntheorem elementary_face_count (P : CollapsePair V) :\n    (faceSet P.ambient).card = (faceSet P.retained).card + 2", DescribeRole.Theorem),
            Node("decl-4", "sequence_face_count", "sequence_face_count", "Every actual step removes two distinct nonempty faces.", "Source variable context (not a compiled telescope):\nvariable {V : Type*} [Fintype V] [DecidableEq V]\n\ntheorem sequence_face_count {K L : PreAbstractSimplicialComplex V}\n    (S : Sequence K L) :\n    (faceSet K).card = (faceSet L).card + 2 * S.pairs.length", DescribeRole.Theorem),
            Node("decl-5", "pair_ambient_le_source", "pair_ambient_le_source", "The exact source contract below specifies D5.S3.Geometry.FiniteMatchingCollapse.pair_ambient_le_source.", "Source variable context (not a compiled telescope):\nvariable {V : Type*} [Fintype V] [DecidableEq V]\n\ntheorem pair_ambient_le_source {K L : PreAbstractSimplicialComplex V}\n    (S : Sequence K L) (P : CollapsePair V) (hP : P ∈ S.pairs) : P.ambient ≤ K", DescribeRole.Theorem),
            Node("decl-6", "sequence_lowers_nodup", "sequence_lowers_nodup", "The exact source contract below specifies D5.S3.Geometry.FiniteMatchingCollapse.sequence_lowers_nodup.", "Source variable context (not a compiled telescope):\nvariable {V : Type*} [Fintype V] [DecidableEq V]\n\ntheorem sequence_lowers_nodup {K L : PreAbstractSimplicialComplex V}\n    (S : Sequence K L) : (S.pairs.map CollapsePair.lower).Nodup", DescribeRole.Theorem),
            Node("decl-7", "matching_pair_occurs", "matching_pair_occurs", "The exact source contract below specifies D5.S3.Geometry.FiniteMatchingCollapse.matching_pair_occurs.", "Source variable context (not a compiled telescope):\nvariable {V : Type*} [Fintype V] [DecidableEq V]\n\ntheorem matching_pair_occurs {K L T : PreAbstractSimplicialComplex V}\n    (M : Pairing K) (S : Sequence L T)\n    (hS : ∀ P ∈ S.pairs, (P.lower, P.apex) ∈ M.pairs)\n    (e : Finset V × V) (he : e ∈ M.pairs) (hl : e.1 ∈ L) :\n    (∃ P ∈ S.pairs, (P.lower, P.apex) = e) ↔ e.1 ∉ T", DescribeRole.Theorem),
            Node("decl-8", "frames_supported", "frames_supported", "The exact source contract below specifies D5.S3.Geometry.FiniteMatchingCollapse.frames_supported.", "Source variable context (not a compiled telescope):\nvariable {V : Type*} [Fintype V] [DecidableEq V]\n\ntheorem frames_supported {K L : PreAbstractSimplicialComplex V} (S : Sequence K L)\n    (W : Finset V) (hW : ∀ s ∈ K, s ⊆ W)\n    (J : PreAbstractSimplicialComplex V) (hJ : J ∈ S.frames) :\n    ∀ s ∈ J, s ⊆ W", DescribeRole.Theorem),
            Node("decl-9", "Pairing.sequence_exists", "Pairing.sequence_exists", "Actual finite extraction, including its integration invariant: every pair in the native sequence is one of the original matching pairs.", "Source variable context (not a compiled telescope):\nvariable {V : Type*} [Fintype V] [DecidableEq V]\nvariable {K : PreAbstractSimplicialComplex V} (M : Pairing K)\n\ntheorem sequence_exists (hacyc : M.IsAcyclic)\n    (T : PreAbstractSimplicialComplex V) (hTK : T ≤ K) (hT : M.Saturated T)\n    (L : PreAbstractSimplicialComplex V) (hLK : L ≤ K) (hTL : T ≤ L)\n    (hL : M.Saturated L) (hcrit : ∀ s ∈ L, M.Unmatched s → s ∈ T) :\n    ∃ S : Sequence L T, ∀ P ∈ S.pairs,\n      (P.lower, P.apex) ∈ M.pairs", DescribeRole.Theorem),
            Node("decl-10", "Pairing.collapseBetween", "Pairing.collapseBetween", "A definite finite native sequence, chosen from the construction above.", "Source variable context (not a compiled telescope):\nvariable {V : Type*} [Fintype V] [DecidableEq V]\nvariable {K : PreAbstractSimplicialComplex V} (M : Pairing K)\n\ndef collapseBetween (hacyc : M.IsAcyclic)\n    (T : PreAbstractSimplicialComplex V) (hTK : T ≤ K) (hT : M.Saturated T)\n    (L : PreAbstractSimplicialComplex V) (hLK : L ≤ K) (hTL : T ≤ L)\n    (hL : M.Saturated L) (hcrit : ∀ s ∈ L, M.Unmatched s → s ∈ T) : Sequence L T", DescribeRole.Definition),
            Node("decl-11", "Pairing.collapseBetween_pairs", "Pairing.collapseBetween_pairs", "The exact source contract below specifies D5.S3.Geometry.FiniteMatchingCollapse.Pairing.collapseBetween_pairs.", "Source variable context (not a compiled telescope):\nvariable {V : Type*} [Fintype V] [DecidableEq V]\nvariable {K : PreAbstractSimplicialComplex V} (M : Pairing K)\n\ntheorem collapseBetween_pairs (hacyc : M.IsAcyclic)\n    (T : PreAbstractSimplicialComplex V) (hTK : T ≤ K) (hT : M.Saturated T)\n    (L : PreAbstractSimplicialComplex V) (hLK : L ≤ K) (hTL : T ≤ L)\n    (hL : M.Saturated L) (hcrit : ∀ s ∈ L, M.Unmatched s → s ∈ T) (P : CollapsePair V)\n    (hP : P ∈ (M.collapseBetween hacyc T hTK hT L hLK hTL hL hcrit).pairs) :\n    (P.lower, P.apex) ∈ M.pairs", DescribeRole.Theorem),
            Node("decl-12", "Pairing.sdrBetween", "Pairing.sdrBetween", "Native original-coordinate SDR, fixing ALL of the target.", "Source variable context (not a compiled telescope):\nvariable {V : Type*} [Fintype V] [DecidableEq V]\nvariable {K : PreAbstractSimplicialComplex V} (M : Pairing K)\n\ndef sdrBetween (hacyc : M.IsAcyclic)\n    (T : PreAbstractSimplicialComplex V) (hTK : T ≤ K) (hT : M.Saturated T)\n    (L : PreAbstractSimplicialComplex V) (hLK : L ≤ K) (hTL : T ≤ L)\n    (hL : M.Saturated L) (hcrit : ∀ s ∈ L, M.Unmatched s → s ∈ T) : RelativeSDR L T hTL", DescribeRole.Definition))));

